SELECT ID ,BIZ_NO ,get_bizno_to_compname(BIZ_NO) "COMP_NM" ,LOGIN ,NAME ,TEL ,EMAIL ,HIRE_DATE ,GENDER_CD ,get_sub_code_name(GENDER_CD)"GENDER_NM" ,ADMIN_CD ,get_sub_code_name(ADMIN_CD) as "ADMIN_NM" ,STATUS_CD ,get_sub_code_name(STATUS_CD) "STATUS_NM" ,CREATED_ON ,PW_UPDATED_ON ,PRJ_MANAGER_CD ,get_sub_code_name(PRJ_MANAGER_CD) "PRJ_MANAGER_NM" ,MCP_CD ,get_sub_code_name(MCP_CD) "MCP_NM" FROM users
AND ADMIN_CD = #{adminCd}
ORDER BY ID
